package dev.slithergoh.pixelmonradar.client;
import com.mojang.blaze3d.vertex.PoseStack;import com.pixelmonmod.pixelmon.api.extensions.PixelmonPlayerExtension;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiEvent;import org.joml.AxisAngle4f;import org.joml.Quaternionf;import java.util.*;
@EventBusSubscriber(modid="pixelmonradar",value=Dist.CLIENT)public final class RadarHud{
 @SubscribeEvent public static void render(RenderGuiEvent.Post e){if(!RadarSettings.hudEnabled)return;Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.screen!=null)return;List<PokemonInfo>all=PokemonScanner.scan();ArrayList<PokemonInfo>list=new ArrayList<>(all);list.sort(Comparator.comparingInt(RadarHud::priority).reversed().thenComparing((PokemonInfo p)->p.dexCaught()?1:0).thenComparingDouble(PokemonInfo::distance));GuiGraphics g=e.getGuiGraphics();int shown=Math.min(4,list.size()),w=176,h=29+shown*22+(list.size()>shown?10:0);round(g,6,6,6+w,6+h,10,0xD80A1218);round(g,6,6,9,6+h,2,0xFF47BCE8);g.drawString(mc.font,"ATLAS",16,12,0xFFF4F8FA,true);g.drawString(mc.font,list.size()+" nearby",6+w-58,12,0xFF8DB1C1,false);try{var dex=((PixelmonPlayerExtension)mc.player).getPokedexNow();if(dex!=null)g.drawString(mc.font,dex.countCaught()+" caught / "+dex.countSeen()+" seen",16,23,0xFF6F929F,false);}catch(Exception ignored){}
 int y=39;for(int i=0;i<shown;i++){PokemonInfo p=list.get(i);boolean tr=p.entityId()==RadarSettings.trackedEntityId;int ac=accent(p);if(tr)round(g,11,y-3,6+w-7,y+18,6,0xAA21483E);if(p.sprite()!=null)g.blit(p.sprite(),13,y-1,0,0,18,18,18,18);String n=p.name();if(mc.font.width(n)>78)n=mc.font.plainSubstrByWidth(n,75)+"…";g.drawString(mc.font,n,35,y,p.rare()?ac:0xFFE8EEF1,true);String dex=p.dexCaught()?"CAUGHT":p.dexSeen()?"SEEN":"NEW";int dc=p.dexCaught()?0xFF70C990:p.dexSeen()?0xFFFFC85C:0xFF62D7FF;g.drawString(mc.font,dex,35,y+10,dc,false);g.drawString(mc.font,Math.round(p.distance())+"m",6+w-32,y+4,0xFF9FB1B9,false);y+=22;}if(list.size()>shown)g.drawString(mc.font,"+"+(list.size()-shown)+" more  •  R opens Atlas",16,y,0xFF718995,false);if(RadarSettings.raidHud){var raids=RaidScanner.scan();if(!raids.isEmpty()){var r=raids.get(0);int rw=176,rx=g.guiWidth()-rw-7,ry=7;round(g,rx,ry,rx+rw,ry+39,9,0xD80A1218);round(g,rx,ry,rx+3,ry+39,2,0xFFFF5F73);if(r.sprite()!=null)g.blit(r.sprite(),rx+8,ry+7,0,0,25,25,25,25);g.drawString(mc.font,r.stars()+"★ RAID  "+r.name(),rx+39,ry+9,0xFFFFD4DA,true);g.drawString(mc.font,Math.round(r.distance())+"m  •  "+direction(mc,r.pos()),rx+39,ry+22,0xFF9DB2BC,false);}}for(PokemonInfo p:list)if(p.entityId()==RadarSettings.trackedEntityId){renderTracker(g,mc,p);break;}}
 private static void renderTracker(GuiGraphics g,Minecraft mc,PokemonInfo p){double dx=p.pos().getX()+.5-mc.player.getX(),dz=p.pos().getZ()+.5-mc.player.getZ();double target=Math.toDegrees(Math.atan2(-dx,dz)),rel=wrap(target-mc.player.getYRot());int cx=g.guiWidth()/2,w=208,left=cx-w/2;int ac=accent(p);round(g,left,7,left+w,47,9,0xE00A1218);round(g,left,7,left+w,10,2,ac);if(p.sprite()!=null)g.blit(p.sprite(),left+8,13,0,0,27,27,27,27);String dex=p.dexCaught()?"CAUGHT":p.dexSeen()?"SEEN":"NEW";g.drawString(mc.font,p.name()+"  Lv."+p.level()+"  "+dex,left+41,14,p.rare()?ac:0xFFFFFFFF,true);g.drawString(mc.font,Math.round(p.distance())+"m  •  "+direction(mc,p.pos())+"  •  Y "+p.pos().getY(),left+41,28,0xFF9DB2BC,false);PoseStack ps=g.pose();ps.pushPose();ps.translate(left+w-18,27,0);ps.mulPose(new Quaternionf(new AxisAngle4f((float)Math.toRadians(-rel),0,0,1)));g.fill(-2,-10,2,7,ac);g.fill(-6,-7,7,-3,ac);ps.popPose();}
 private static int priority(PokemonInfo p){if(p.shiny())return 100;if(p.legendary()||p.mythical())return 90;if(p.ultraBeast()||p.paradox())return 80;if(p.boss())return 70;if(!p.dexCaught())return 15;return 0;}private static int accent(PokemonInfo p){if(p.shiny())return 0xFF62FFFF;if(p.legendary()||p.mythical())return 0xFFFFB64F;if(p.ultraBeast()||p.paradox())return 0xFFB987FF;if(p.boss())return 0xFFFF6666;if(!p.dexCaught())return 0xFF62D7FF;return 0xFF4EB7DD;}private static String direction(Minecraft mc,net.minecraft.core.BlockPos p){double dx=p.getX()+.5-mc.player.getX(),dz=p.getZ()+.5-mc.player.getZ();double a=(Math.toDegrees(Math.atan2(-dx,dz))+360)%360;String[]d={"N","NE","E","SE","S","SW","W","NW"};return d[(int)Math.round(a/45)%8];}private static double wrap(double a){while(a<=-180)a+=360;while(a>180)a-=360;return a;}private static void round(GuiGraphics g,int l,int t,int r,int b,int rad,int c){if(r<=l||b<=t)return;rad=Math.max(1,Math.min(rad,Math.min((r-l)/2,(b-t)/2)));g.fill(l+rad,t,r-rad,b,c);g.fill(l,t+rad,r,b-rad,c);for(int i=0;i<rad;i++){int in=(int)Math.ceil(rad-Math.sqrt(Math.max(0,rad*rad-(rad-i)*(rad-i))));g.fill(l+in,t+i,r-in,b-i,c);}}
}